const FrameworkAdvisoryWarnings: React.FC<{ warnings: string[]; max?: number }> = ({
  warnings,
  max = 2,
}) => {
  if (!warnings.length) {
    return null;
  }
  return (
    <>
      {warnings.slice(0, max).map((warning) => (
        <Typography
          key={warning}
          variant="caption"
          color="warning.main"
          display="block"
          sx={{ mt: 0.5 }}
        >
          {warning}
        </Typography>
      ))}
    </>
  );
};

