const isBrsrDisclosurePrepReady = (summary?: BrsrComplianceSummary) => Boolean(
  summary?.disclosurePrepReady ?? summary?.isBRSRCompliant
);

const resolveBrsrSubmissionScore = (
  summary?: BrsrComplianceSummary,
  framework?: FrameworkReadinessSnapshot
) => summary?.submissionReadinessPercent
  ?? summary?.readinessScore
  ?? framework?.submissionReadinessScore
  ?? framework?.score
  ?? 0;

const resolveBrsrDisclosureScore = (
  summary?: BrsrComplianceSummary,
  framework?: FrameworkReadinessSnapshot
) => summary?.disclosureReadinessPercent
  ?? framework?.disclosurePrepScore
  ?? 0;

const BUYER_FRAMEWORK_KEYS = ['CDP', 'CSRD', 'TCFD', 'GRI', 'EUDR', 'ECOVADIS'] as const;

const renderRemediationTrack = (
  title: string,
  items: RemediationItem[],
  limit = 6
) => {
  if (!items.length) return null;
  return (
    <Box sx={{ mb: 2 }}>
      <Typography variant="subtitle2" gutterBottom>{title}</Typography>
      {items.slice(0, limit).map((item) => {
        const hubLink = item.hubLink || remediationLinkForBlockedReason(item.action);
        const actionLabel = remediationActionLabelForBlockedReason(item.action);
        return (
          <Box key={`${item.framework}-${item.action}-${item.field || ''}`} sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 0.5, flexWrap: 'wrap' }}>
            <Chip size="small" label={item.framework} variant="outlined" sx={{ mt: 0.25 }} />
            {item.needsVerification ? (
              <Chip size="small" label="Verify" color="info" variant="outlined" sx={{ mt: 0.25 }} />
            ) : null}
            <Typography variant="body2" component="span" sx={{ flex: 1 }}>
              {item.action}
              {item.detail ? ` — ${item.detail}` : ''}
            </Typography>
            {hubLink ? (
              <Button size="small" component={RouterLink} to={hubLink} sx={{ ml: 'auto', flexShrink: 0 }}>
                {actionLabel}
              </Button>
            ) : null}
          </Box>
        );
      })}
    </Box>
  );
};

