  const theme = useTheme();
  const location = useLocation();
  const isMsmeSimplified = isMsmeAppPath(location.pathname);
  const { strings } = useReadinessLocale();
  const { t } = useAppTranslation();
  const queryClient = useQueryClient();
  useOrchestrationEvents(true);
  const isDark = theme.palette.mode === 'dark';
  const chartGrid = cartesianGridStroke(isDark);
  const chartTip = rechartsTooltipProps(isDark);
  const tickAxis = axisTickForMode(isDark);
  const chartMotion = chartAnimationPropsFor(usePrefersReducedMotion());

  const [tabValue, setTabValue] = useUrlTabParam(0, { maxTab: REPORTING_TAB_COUNT - 1 });
  const [dateRange, setDateRange] = useState<ReportingDateRange>('1year');
  const [exportDialogOpen, setExportDialogOpen] = useState(false);
  const [previewBlobUrl, setPreviewBlobUrl] = useState<string | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [previewFileName, setPreviewFileName] = useState('report.pdf');
  const [previewReady, setPreviewReady] = useState(false);
  const cachedExportBlobRef = useRef<Blob | null>(null);
