  const brsrScopePieData = useMemo(() => {
    const buildScopePercentRows = (scope1: number, scope2: number, scope3: number) => {
      const s1 = Number(scope1) || 0;
      const s2 = Number(scope2) || 0;
      const s3 = Number(scope3) || 0;
      const total = s1 + s2 + s3;
      if (total <= 0) {
        return [];
      }
      const looksLikePercent = total <= 100.5 && s1 <= 100 && s2 <= 100 && s3 <= 100;
      const rows = looksLikePercent
        ? [
          { name: 'Scope 1', value: s1 },
          { name: 'Scope 2', value: s2 },
          { name: 'Scope 3', value: s3 },
        ]
        : [
          { name: 'Scope 1', value: (s1 / total) * 100 },
          { name: 'Scope 2', value: (s2 / total) * 100 },
          { name: 'Scope 3', value: (s3 / total) * 100 },
        ];
      return rows.filter((row) => row.value > 0);
    };

    const pct = brsrReport?.environmental?.greenhouseGasEmissions?.scopeContributionPercent;
    if (pct) {
      const fromPct = buildScopePercentRows(pct.scope1, pct.scope2, pct.scope3);
      if (fromPct.length > 0) {
        return fromPct;
      }
    }

    const ghg = brsrReport?.environmental?.greenhouseGasEmissions;
    if (ghg) {
      const fromGhg = buildScopePercentRows(
        ghg.scope1 ?? 0,
        ghg.scope2 ?? 0,
        ghg.scope3 ?? 0,
      );
      if (fromGhg.length > 0) {
        return fromGhg;
      }
    }

    const scopeData = reportingFootprint?.scopeData;
    if (scopeData) {
      const fromFootprint = buildScopePercentRows(
        scopeData.scope1?.percentage ?? scopeData.scope1?.total,
        scopeData.scope2?.percentage ?? scopeData.scope2?.total,
        scopeData.scope3?.percentage ?? scopeData.scope3?.total,
      );
      if (fromFootprint.length > 0) {
        return fromFootprint;
      }
    }

    return [];
  }, [brsrReport, reportingFootprint]);

