        readinessLevel: iso14067FrameworkContext.readinessLevel,
        readinessLabel: iso14067FrameworkContext.readinessLabel,
        readinessType: iso14067FrameworkContext.readinessType,
        blockedReasons: iso14067FrameworkContext.blockedReasons,
